// 📁 src/app/pages/home/home.component.ts

import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { Observable, Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

// Importar desde la nueva arquitectura
import { Property } from '../../core/models/property.interface';
import { SearchParams } from '../../core/models/search.interface';
import { PropertyService } from '../../core/services/property.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './home.component.html',
  styleUrl: './home.component.scss'
})
export class HomeComponent implements OnInit, OnDestroy {
  
  // 🎯 DATOS REACTIVOS
  featuredProperties$: Observable<Property[]>;
  
  // 📊 ESTADO SIMPLIFICADO
  isLoading = true;
  searchError: string | null = null;
  
  // 🔍 FORMULARIO DE BÚSQUEDA
  searchData: SearchParams = {
    destination: '',
    checkIn: '',
    checkOut: '',
    guests: 2
  };
  
  // 🧹 CLEANUP
  private destroy$ = new Subject<void>();

  // 📅 FECHAS MÍNIMAS
  readonly today = new Date().toISOString().split('T')[0];
  readonly tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];

  // 🚀 SUGERENCIAS RÁPIDAS SIMPLIFICADAS
  readonly quickSuggestions = [
    { destination: 'valle-cocora', label: 'Valle de Cocora', icon: '🏔️' },
    { destination: 'salento', label: 'Fincas Cafeteras', icon: '☕' },
    { destination: 'armenia', label: 'Armenia Centro', icon: '🏛️' },
    { destination: 'filandia', label: 'Turismo Rural', icon: '🌿' }
  ];

  // 🗺️ DESTINOS PRINCIPALES
  readonly popularDestinations = [
    {
      key: 'salento',
      name: 'Salento',
      description: 'Pueblo patrimonio con arquitectura colonial y puerta al Valle de Cocora',
      image: 'https://images.unsplash.com/photo-1611273426858-450d8e3c9fce?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80'
    },
    {
      key: 'armenia',
      name: 'Armenia Centro',
      description: 'Capital del Quindío con museos, parques y la mejor gastronomía regional',
      image: 'https://images.unsplash.com/photo-1577962917302-cd874c4e31d2?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80'
    },
    {
      key: 'filandia',
      name: 'Filandia',
      description: 'El "Balcón del Quindío" con vistas panorámicas y arquitectura paisa',
      image: 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80'
    }
  ];

  constructor(
    private propertyService: PropertyService,
    private router: Router
  ) {
    // 🔄 Inicializar datos
    this.featuredProperties$ = this.propertyService.getFeaturedProperties();
  }

  ngOnInit(): void {
    this.loadFeaturedProperties();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  /**
   * 🔄 Cargar propiedades destacadas
   */
  private loadFeaturedProperties(): void {
    this.isLoading = true;
    
    this.featuredProperties$
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (properties) => {
          this.isLoading = false;
          console.log('✅ Propiedades destacadas cargadas:', properties.length);
        },
        error: (error) => {
          this.isLoading = false;
          console.error('❌ Error cargando propiedades:', error);
        }
      });
  }

  /**
   * 🔍 BÚSQUEDA PRINCIPAL
   */
  onSearchSubmit(form: any): void {
    if (form.valid) {
      this.performSearch();
    } else {
      this.searchError = 'Por favor completa todos los campos';
    }
  }

  /**
   * 🔍 Ejecutar búsqueda
   */
  private performSearch(): void {
    // Validación simple
    if (!this.searchData.destination) {
      this.searchError = 'Selecciona un destino';
      return;
    }

    if (!this.searchData.checkIn || !this.searchData.checkOut) {
      this.searchError = 'Selecciona las fechas';
      return;
    }

    // Validar que checkout sea después de checkin
    if (new Date(this.searchData.checkOut) <= new Date(this.searchData.checkIn)) {
      this.searchError = 'La fecha de salida debe ser posterior a la llegada';
      return;
    }

    // Limpiar errores y navegar
    this.searchError = null;
    this.navigateToSearch();
  }

  /**
   * 🧭 Navegar a resultados de búsqueda
   */
  private navigateToSearch(): void {
    this.router.navigate(['/search'], { 
      queryParams: {
        destination: this.searchData.destination,
        checkIn: this.searchData.checkIn,
        checkOut: this.searchData.checkOut,
        guests: this.searchData.guests
      }
    });

    // Analytics
    this.trackInteraction('search_performed', this.searchData);
  }

  /**
   * 🚀 Búsqueda rápida desde sugerencias
   */
  searchDestination(destination: string): void {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    
    const dayAfter = new Date();
    dayAfter.setDate(dayAfter.getDate() + 3);

    this.searchData = {
      destination,
      checkIn: tomorrow.toISOString().split('T')[0],
      checkOut: dayAfter.toISOString().split('T')[0],
      guests: 2
    };

    this.navigateToSearch();
    this.trackInteraction('quick_search', { destination });
  }

  /**
   * 🏠 Ver detalles de propiedad
   */
  viewPropertyDetails(propertyId: string): void {
    // Registrar vista
    this.propertyService.incrementPropertyViews(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe();

    // Navegar
    this.router.navigate(['/property', propertyId]);
    this.trackInteraction('property_view', { propertyId });
  }

  /**
   * ❤️ Toggle favorito
   */
  toggleFavorite(propertyId: string, event: Event): void {
    event.stopPropagation();
    
    this.propertyService.toggleFavorite(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (isFavorite) => {
          console.log(`${isFavorite ? '❤️' : '🤍'} Favorito:`, propertyId);
          this.trackInteraction('favorite_toggle', { propertyId, isFavorite });
        },
        error: (error) => {
          console.error('❌ Error favorito:', error);
        }
      });
  }

  /**
   * 🗺️ Ver todas las propiedades
   */
  viewAllProperties(): void {
    this.router.navigate(['/search']);
    this.trackInteraction('view_all_properties');
  }

  /**
   * 🏷️ Obtener nombre amigable del tipo de propiedad
   */
  getPropertyTypeName(type: string): string {
    const types: { [key: string]: string } = {
      'finca': 'Finca Cafetera',
      'cabana': 'Cabaña Ecológica',
      'hacienda': 'Hacienda',
      'glamping': 'Glamping',
      'hotel': 'Hotel Boutique'
    };
    return types[type] || type;
  }

  /**
   * 📝 TrackBy para optimización
   */
  trackByPropertyId(index: number, property: Property): string {
    return property.id;
  }

  /**
   * 🎯 Analytics simplificado
   */
  trackInteraction(action: string, data?: any): void {
    console.log(`📊 Home Action: ${action}`, data);
    
    // Aquí integrarías con Google Analytics, Mixpanel, etc.
    // gtag('event', action, {
    //   event_category: 'home_page',
    //   event_label: data ? JSON.stringify(data) : undefined
    // });
  }

  /**
   * 📅 Validar fechas en tiempo real
   */
  onDateChange(): void {
    // Auto-ajustar checkout si es menor o igual a checkin
    if (this.searchData.checkIn && this.searchData.checkOut) {
      const checkIn = new Date(this.searchData.checkIn);
      const checkOut = new Date(this.searchData.checkOut);
      
      if (checkOut <= checkIn) {
        const newCheckOut = new Date(checkIn);
        newCheckOut.setDate(newCheckOut.getDate() + 1);
        this.searchData.checkOut = newCheckOut.toISOString().split('T')[0];
      }
    }
    
    // Limpiar errores al cambiar fechas
    if (this.searchError && this.searchError.includes('fecha')) {
      this.searchError = null;
    }
  }

  /**
   * 🎪 Acciones específicas del CTA
   */
  contactSupport(): void {
    // Implementar chat, WhatsApp, etc.
    console.log('💬 Contactar soporte local');
    this.trackInteraction('contact_support');
    
    // Ejemplo: abrir WhatsApp
    // window.open('https://wa.me/573001234567?text=Hola, necesito ayuda con alojamientos en el Quindío', '_blank');
  }

  /**
   * 🔄 Refresh de propiedades destacadas
   */
  
}
